def backfill_marks(apps, schema_editor):
    """Attempts made before teacher-marking existed keep their automatic score as the final marks,
    so old results do not suddenly show up as 'waiting for teacher'."""
    QuizAttempt = apps.get_model("immersive", "QuizAttempt")
    for a in QuizAttempt.objects.filter(marks__isnull=True):
        a.marks, a.graded_at = a.score, a.created
        a.save(update_fields=["marks", "graded_at"])


